ALTER TABLE public.import_source_evidence ALTER COLUMN booking_id DROP NOT NULL;
CREATE UNIQUE INDEX import_source_evidence_register_batch_unique ON public.import_source_evidence(tenant_id,batch) WHERE booking_id IS NULL;
COMMENT ON COLUMN public.import_source_evidence.booking_id IS 'Individual booking evidence when set; null for a private register-level import batch.';
DO $import$
DECLARE
 t uuid := '75cc6a9e-9d17-4268-92ee-8b595c842dee'; batch_name text := 'daycare-master-2026-11-23';
 r record; cid uuid; pid uuid; eid uuid; plan_id uuid; verified_pid uuid; n integer; ndays integer; selected text[]; canonical text; note text; original_finance jsonb; final_finance jsonb;
BEGIN
 PERFORM pg_advisory_xact_lock(hashtextextended(t::text||':daycare-master-import',0));
 IF EXISTS(SELECT 1 FROM public.import_source_evidence WHERE tenant_id=t AND batch=batch_name) THEN RAISE EXCEPTION 'This daycare register has already been imported'; END IF;
 LOCK TABLE public.daycare_enrolments IN SHARE ROW EXCLUSIVE MODE;
 IF EXISTS(SELECT 1 FROM public.daycare_enrolments WHERE tenant_id=t AND active) THEN RAISE EXCEPTION 'Active enrolments already exist: reconcile rather than duplicate'; END IF;
 IF NOT EXISTS(SELECT 1 FROM pg_trigger WHERE tgrelid='public.daycare_enrolments'::regclass AND tgname='trg_daycare_enrolments_prorata' AND tgenabled='O') THEN RAISE EXCEPTION 'Unexpected pro-rata trigger state'; END IF;
 SELECT jsonb_build_object('invoices',(SELECT md5(coalesce(jsonb_agg(to_jsonb(x) ORDER BY id)::text,'[]')) FROM public.invoices x WHERE tenant_id=t),'items',(SELECT md5(coalesce(jsonb_agg(to_jsonb(x) ORDER BY id)::text,'[]')) FROM public.invoice_items x WHERE tenant_id=t),'quotes',(SELECT md5(coalesce(jsonb_agg(to_jsonb(x) ORDER BY id)::text,'[]')) FROM public.estimates x WHERE tenant_id=t),'payments',(SELECT md5(coalesce(jsonb_agg(to_jsonb(x) ORDER BY id)::text,'[]')) FROM public.payments x WHERE tenant_id=t),'messages',(SELECT md5(coalesce(jsonb_agg(to_jsonb(x) ORDER BY id)::text,'[]')) FROM public.notification_events x WHERE tenant_id=t),'queue',(SELECT md5(coalesce(jsonb_agg(to_jsonb(x) ORDER BY id)::text,'[]')) FROM public.xero_sync_queue x WHERE tenant_id=t),'settings',(SELECT to_jsonb(x) FROM public.invoicing_settings x WHERE tenant_id=t),'xero',(SELECT to_jsonb(x) FROM public.xero_settings x WHERE tenant_id=t)) INTO original_finance;
 CREATE TEMP TABLE daycare_master_source(source_row integer,customer_number text,source_pet text,day_mask integer) ON COMMIT DROP;
 INSERT INTO daycare_master_source VALUES
(2,'SK00003','Oliver',21),(3,'SK05114','Lilly',3),(4,'SK00061','Alfie',4),(5,'SK01287','Luke',21),(6,'SK00092','Armani',1),(7,'SK00985','Blair',9),(8,'SK00985','Hunter',9),(9,'SK01978','Ella',16),(10,'SK01978','Nova',16),(11,'SK01978','Ruby',16),(12,'SK01978','Toby',16),(13,'SK00821','Fergus',4),(14,'SK01134','Lady Vira',8),(15,'SK05084','Dudley',1),(16,'SK02617','Zeus',4),(17,'SK00086','Archie',16),(18,'SK02676','Rayne',4),(19,'SK02676','Slipper',4),(20,'SK02676','Tsala',4),(21,'SK02416','Charlie',2),(22,'SK01387','Max',10),(23,'SK02767','Archie',3),(24,'SK02832','Sunny',10),(25,'SK00370','Henry',2),(26,'SK00370','Sally',2),(27,'SK01393','Hugo',4),(28,'SK02881','Bianca',5),(29,'SK02896','Kelly',10),(30,'SK02894','Ollie',4),(31,'SK02907','Remy',8),(32,'SK02923','Juno',21),(33,'SK00879','Georgie',2),(34,'SK02966','Lady Luna',4),(35,'SK01246','Hela',2),(36,'SK01246','Loki',10),(37,'SK02413','Baymax',4),(38,'SK02413','Bear',4),(39,'SK02413','Captain',4),(40,'SK04484','Ollie',4),(41,'SK03135','Squidy',12),(42,'SK04495','Griffin',9),(43,'SK00263','Benji',1),(44,'SK00263','Brian',1),(45,'SK03169','Django',18),(46,'SK03186','Riley',21),(47,'SK03188','Bella',2),(48,'SK03188','Teddy',2),(49,'SK01026','Jasmine',4),(50,'SK01026','Jasper',4),(51,'SK03289','Marsh',10),(52,'SK03329','Ozzie',4),(53,'SK03332','Odin',4),(54,'SK03332','Raven',4),(55,'SK03359','Goose',9),(56,'SK03359','Zoey',11),(57,'SK03359','Zoey',11),(58,'SK04526','Tatertot',9),(59,'SK00896','Gizmo',21),(60,'SK01563','Mr.Darcy',4),(61,'SK01563','Queen',4),(62,'SK01563','Samantha',4),(63,'SK03408','Dexter',8),(64,'SK03408','Jess',8),(65,'SK00120','Avery',31),(66,'SK00268','Benji',9),(67,'SK01141','Lara',2),(68,'SK01141','April',2),(69,'SK03430','Layla',11),(70,'SK01116','Koba',18),(71,'SK03458','Miley',16),(72,'SK04537','Kingston',2),(73,'SK00799','Ellie',16),(74,'SK03502','Max',4),(75,'SK03502','Theodore',4),(76,'SK04520','Eden',17),(77,'SK03526','Yang',17),(78,'SK03526','Yin',17),(79,'SK03547','Ragnar',17),(80,'SK03549','Boo',18),(81,'SK02448','Sadie',10),(82,'SK03587','Hudson',8),(83,'SK03587','Stella',8),(84,'SK01223','Lily',8),(85,'SK03590','Zac',4),(86,'SK03628','Bella',12),(87,'SK03634','McGregor',9),(88,'SK03656','Tokyo',31),(89,'SK00150','Bailey',4),(90,'SK00150','Oreo',4),(91,'SK00649','Cooper',31),(92,'SK03790','Blaze',16),(93,'SK03814','El Chapo',4),(94,'SK03814','Pablo',4),(95,'SK00804','Aston',26),(96,'SK04605','Chewbacca',10),(97,'SK03856','Amy',8),(98,'SK00804','Enzo',26),(99,'SK00275','Benji',9),(100,'SK00275','Lexi',9),(101,'SK03876','Khovie',7),(102,'SK03909','Sebastian',4),(103,'SK00989','Hunter',5),(104,'SK04618','Mila',2),(105,'SK01755','Peppa',14),(106,'SK00377','Atreyu',4),(107,'SK00377','Maddie',4),(108,'SK00377','Zelda',4),(109,'SK04017','Suki',16),(110,'SK04051','Pickle',2),(111,'SK04089','Joey',16),(112,'SK04089','Luna',16),(113,'SK04106','Lilly',25),(114,'SK04651','Ocean',1),(115,'SK04149','Cody',18),(116,'SK04152','Sam',16),(117,'SK05010','Knox',3),(118,'SK04167','Lucy',4),(119,'SK04171','Arlo',16),(120,'SK04171','Rey',16),(121,'SK00545','Cloe',31),(122,'SK00606','Coco',3),(123,'SK02455','Tug',5),(124,'SK00374','Gaia',17),(125,'SK00374','Pegasus',17),(126,'SK05113','Mr Ruffles',20),(127,'SK01915','Rocco',8),(128,'SK04261','Kaisa',4),(129,'SK04261','Titan',4),(130,'SK04269','Khush',9),(131,'SK04292','Abby',20),(132,'SK04292','Jackson',20),(133,'SK01546','Fred',17),(134,'SK01546','Molly-Moo',17),(135,'SK01631','Levi',18),(136,'SK01631','Mila',18),(137,'SK04327','Dusty',8),(138,'SK04327','Max',8),(139,'SK04335','Mali',16),(140,'SK02412','Zeus',2),(141,'SK04752','Sonny',18),(142,'SK04689','Spike',14),(143,'SK03910','Taite',17),(144,'SK03910','Willow',17),(145,'SK04690','Max',18),(146,'SK04690','Patches',18),(147,'SK04385','Jack',1),(148,'SK04385','Troy',1),(149,'SK04390','Juca',16),(150,'SK04390','Zara',16),(151,'SK04043','Juno-Mae',18);
 IF (SELECT count(*) FROM daycare_master_source)<>150 OR (SELECT count(*) FROM (SELECT DISTINCT customer_number,source_pet FROM daycare_master_source) x)<>149 THEN RAISE EXCEPTION 'Source row or deduplication count mismatch'; END IF;
 IF EXISTS(SELECT 1 FROM daycare_master_source GROUP BY customer_number,source_pet HAVING count(DISTINCT day_mask)>1) THEN RAISE EXCEPTION 'Conflicting duplicate weekdays'; END IF;
 CREATE TEMP TABLE daycare_master_notes(customer_number text,source_pet text,note text) ON COMMIT DROP;
 INSERT INTO daycare_master_notes VALUES
 ('SK03289','Marsh','Transport requested: Collect & drop. Staff to confirm route, address and times.'),
 ('SK00120','Avery','Repeat grooming requested: Express small every Friday. Staff to confirm appointments.'),
 ('SK03458','Miley','Transport requested: Collect & drop. Staff to confirm route, address and times.'),
 ('SK04520','Eden','Repeat grooming requested: Express small every Monday, and Full every Friday. Staff to confirm appointments.'),
 ('SK00649','Cooper','Allergic to bees.'),
 ('SK04651','Ocean','Weekday confirmation needed: not known which day. Monday is provisional from the register.'),
 ('SK05010','Knox','Weekday confirmation needed: not known which days. Monday and Tuesday are provisional from the register.'),
 ('SK02455','Tug','Transport requested: Collect & drop. Staff to confirm route, address and times. Register says Bull Terrier; existing Tugg profile says Jack Russell. Breed needs confirmation; existing profile preserved.');
 FOR r IN SELECT * FROM (VALUES ('SK05010','Shivonn Cunha','Shivonn','Cunha'),('SK04752','Violeta Markovic','Violeta','Markovic')) x(num,name,first_name,last_name) LOOP
  IF EXISTS(SELECT 1 FROM public.customers WHERE tenant_id=t AND (customer_number=r.num OR lower(full_name)=lower(r.name))) THEN RAISE EXCEPTION 'Missing customer now exists: %',r.num; END IF;
  INSERT INTO public.customers(tenant_id,customer_number,full_name,first_name,last_name,import_source,import_batch,imported_at) VALUES(t,r.num,r.name,r.first_name,r.last_name,'Charlotte daycare master register',batch_name,now());
 END LOOP;
 FOR r IN SELECT * FROM (VALUES
 ('SK05114','Lilly','Bernedoodle',NULL::text,'unknown'),('SK05084','Dudley',NULL,NULL,'unknown'),('SK03332','Odin','German Shepherd',NULL,'male'),('SK03332','Raven','German Shepherd',NULL,'female'),('SK01563','Queen','Mixed Breed',NULL,'female'),('SK05010','Knox','French Bulldog',NULL,'unknown'),('SK05113','Mr Ruffles','Pomeranian','small','male'),('SK04752','Sonny','Miniature Poodle',NULL,'unknown'),('SK03910','Willow','Great Dane','large','female')) x(num,name,breed,size,sex) LOOP
  SELECT id INTO STRICT cid FROM public.customers WHERE tenant_id=t AND customer_number=r.num;
  IF EXISTS(SELECT 1 FROM public.pets WHERE tenant_id=t AND customer_id=cid AND lower(name)=lower(r.name)) THEN RAISE EXCEPTION 'New pet now exists: % %',r.num,r.name; END IF;
  INSERT INTO public.pets(tenant_id,customer_id,pet_number,name,species,breed,size,sex,import_source,import_batch,imported_at) VALUES(t,cid,public.next_pet_number(t),r.name,'dog',r.breed,r.size::public.pet_size,r.sex::public.pet_sex,'Charlotte daycare master register',batch_name,now());
 END LOOP;
 CREATE TEMP TABLE daycare_master_mapping(customer_number text,source_pet text,pet_id uuid,enrolment_id uuid,selected_days text[],source_rows integer[]) ON COMMIT DROP;
 -- Only suppress the existing retrospective pro-rata trigger for this transaction; all validation and access rules stay intact.
 ALTER TABLE public.daycare_enrolments DISABLE TRIGGER trg_daycare_enrolments_prorata;
 FOR r IN SELECT customer_number,source_pet,day_mask,array_agg(source_row ORDER BY source_row) source_rows FROM daycare_master_source GROUP BY customer_number,source_pet,day_mask ORDER BY min(source_row) LOOP
  SELECT id INTO STRICT cid FROM public.customers WHERE tenant_id=t AND customer_number=r.customer_number;
  canonical := CASE r.customer_number||':'||r.source_pet
   WHEN 'SK02966:Lady Luna' THEN 'Luna' WHEN 'SK04495:Griffin' THEN 'Gryffin' WHEN 'SK03359:Goose' THEN 'Gose' WHEN 'SK04520:Eden' THEN 'Eden-Toy' WHEN 'SK00377:Atreyu' THEN 'Atreyi' WHEN 'SK00545:Cloe' THEN 'Chloe' WHEN 'SK02455:Tug' THEN 'Tugg' WHEN 'SK01915:Rocco' THEN 'Roco' WHEN 'SK01546:Molly-Moo' THEN 'Molly' WHEN 'SK02412:Zeus' THEN 'Zeuz' WHEN 'SK04690:Max' THEN 'Max Males' WHEN 'SK04043:Juno-Mae' THEN 'Juno' ELSE r.source_pet END;
  verified_pid:=CASE r.customer_number||':'||r.source_pet WHEN 'SK02896:Kelly' THEN '1d08c2f6-cf66-4f76-932d-6181cc0121bd'::uuid WHEN 'SK04618:Mila' THEN 'b9e3b536-710d-46a3-bfb8-170f86fed1b6'::uuid ELSE NULL END;
  IF verified_pid IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.pets WHERE id=verified_pid AND customer_id=cid AND ((r.source_pet='Kelly' AND breed='x breed' AND sex='female') OR (r.source_pet='Mila' AND breed='Labradoodle'))) THEN RAISE EXCEPTION 'Verified duplicate-profile evidence changed'; END IF;
  SELECT count(*) INTO n FROM public.pets WHERE tenant_id=t AND customer_id=cid AND species='dog' AND status='active' AND deceased_at IS NULL AND (verified_pid IS NULL OR id=verified_pid) AND regexp_replace(lower(name),'[^a-z0-9]','','g')=regexp_replace(lower(canonical),'[^a-z0-9]','','g');
  IF n<>1 THEN RAISE EXCEPTION 'Pet identity missing or ambiguous: % % -> % (% matches)',r.customer_number,r.source_pet,canonical,n; END IF;
  SELECT id INTO STRICT pid FROM public.pets WHERE tenant_id=t AND customer_id=cid AND species='dog' AND status='active' AND deceased_at IS NULL AND (verified_pid IS NULL OR id=verified_pid) AND regexp_replace(lower(name),'[^a-z0-9]','','g')=regexp_replace(lower(canonical),'[^a-z0-9]','','g');
  SELECT array_agg(day ORDER BY bit) INTO selected FROM (VALUES (0,'mon'),(1,'tue'),(2,'wed'),(3,'thu'),(4,'fri')) d(bit,day) WHERE (r.day_mask & (1 << bit))<>0;
  ndays:=cardinality(selected);
  SELECT id INTO STRICT plan_id FROM public.daycare_plans WHERE tenant_id=t AND active AND billing_period='month' AND days_per_week=ndays;
  SELECT x.note INTO note FROM daycare_master_notes x WHERE x.customer_number=r.customer_number AND x.source_pet=r.source_pet;
  note:=concat_ws(E'\n','Existing daycare enrolment carried forward on 23 Nov 2026; no new November charge.',note);
  INSERT INTO public.daycare_enrolments(tenant_id,customer_id,pet_id,daycare_plan_id,selected_days,start_date,active,notes) VALUES(t,cid,pid,plan_id,selected,'2026-11-23',true,note) RETURNING id INTO eid;
  INSERT INTO daycare_master_mapping VALUES(r.customer_number,r.source_pet,pid,eid,selected,r.source_rows);
  INSERT INTO public.daycare_attendance(tenant_id,customer_id,pet_id,attendance_date,status,expected,notes)
   SELECT t,cid,pid,'2026-11-23'::date+bit,'expected',true,note FROM (VALUES (0,'mon'),(1,'tue'),(2,'wed'),(3,'thu'),(4,'fri')) d(bit,day) WHERE day=ANY(selected)
   ON CONFLICT(tenant_id,pet_id,attendance_date) DO NOTHING;
  IF r.customer_number='SK00649' AND r.source_pet='Cooper' THEN
   UPDATE public.pets SET medical_notes=concat_ws(E'\n',nullif(medical_notes,''),'Allergic to bees.') WHERE id=pid AND coalesce(medical_notes,'') NOT ILIKE '%allergic to bees%';
  END IF;
  IF EXISTS(SELECT 1 FROM daycare_master_notes x WHERE x.customer_number=r.customer_number AND x.source_pet=r.source_pet AND (x.note LIKE 'Transport requested:%' OR x.note LIKE 'Repeat grooming requested:%')) THEN
   UPDATE public.customers SET notes_internal=concat_ws(E'\n',nullif(notes_internal,''),r.source_pet||' — '||(SELECT x.note FROM daycare_master_notes x WHERE x.customer_number=r.customer_number AND x.source_pet=r.source_pet)) WHERE id=cid;
  END IF;
 END LOOP;
 ALTER TABLE public.daycare_enrolments ENABLE TRIGGER trg_daycare_enrolments_prorata;
 IF (SELECT count(*) FROM daycare_master_mapping)<>149 OR (SELECT count(DISTINCT pet_id) FROM daycare_master_mapping)<>149 THEN RAISE EXCEPTION 'Expected 149 distinct enrolled pets'; END IF;
 IF (SELECT count(*) FROM public.daycare_attendance a JOIN daycare_master_mapping m USING(pet_id) WHERE a.tenant_id=t AND attendance_date BETWEEN '2026-11-23' AND '2026-11-27')<>240 THEN RAISE EXCEPTION 'Expected 240 weekly attendance records'; END IF;
 FOR r IN SELECT * FROM (VALUES ('2026-11-23'::date,47),('2026-11-24'::date,45),('2026-11-25'::date,55),('2026-11-26'::date,41),('2026-11-27'::date,52)) x(day,total) LOOP
  IF (SELECT count(*) FROM public.daycare_attendance a JOIN daycare_master_mapping m USING(pet_id) WHERE tenant_id=t AND attendance_date=r.day AND status='expected' AND expected)<>r.total THEN RAISE EXCEPTION 'Daycare count mismatch for %',r.day; END IF;
 END LOOP;
 IF EXISTS(SELECT 1 FROM public.daycare_enrolments e JOIN daycare_master_mapping m ON m.enrolment_id=e.id WHERE e.invoice_id IS NOT NULL OR e.start_date<>'2026-11-23' OR NOT e.active OR e.customer_id IS DISTINCT FROM (SELECT customer_id FROM public.pets WHERE id=e.pet_id)) THEN RAISE EXCEPTION 'Incorrect enrolment links or retrospective billing'; END IF;
 SELECT jsonb_build_object('invoices',(SELECT md5(coalesce(jsonb_agg(to_jsonb(x) ORDER BY id)::text,'[]')) FROM public.invoices x WHERE tenant_id=t),'items',(SELECT md5(coalesce(jsonb_agg(to_jsonb(x) ORDER BY id)::text,'[]')) FROM public.invoice_items x WHERE tenant_id=t),'quotes',(SELECT md5(coalesce(jsonb_agg(to_jsonb(x) ORDER BY id)::text,'[]')) FROM public.estimates x WHERE tenant_id=t),'payments',(SELECT md5(coalesce(jsonb_agg(to_jsonb(x) ORDER BY id)::text,'[]')) FROM public.payments x WHERE tenant_id=t),'messages',(SELECT md5(coalesce(jsonb_agg(to_jsonb(x) ORDER BY id)::text,'[]')) FROM public.notification_events x WHERE tenant_id=t),'queue',(SELECT md5(coalesce(jsonb_agg(to_jsonb(x) ORDER BY id)::text,'[]')) FROM public.xero_sync_queue x WHERE tenant_id=t),'settings',(SELECT to_jsonb(x) FROM public.invoicing_settings x WHERE tenant_id=t),'xero',(SELECT to_jsonb(x) FROM public.xero_settings x WHERE tenant_id=t)) INTO final_finance;
 IF original_finance IS DISTINCT FROM final_finance THEN RAISE EXCEPTION 'Import changed billing, payments, messages, queues or settings'; END IF;
 IF (SELECT sync_payments FROM public.xero_settings WHERE tenant_id=t) IS DISTINCT FROM false THEN RAISE EXCEPTION 'Xero payment sync must remain off'; END IF;
 INSERT INTO public.import_source_evidence(tenant_id,batch,evidence) VALUES(t,batch_name,jsonb_build_object('file','CB_Sloppy_Kisses_Master_Day_Care_Register_20_Oct_26_UPD2_22_Nov_2.xlsx','sheet','New Printed Weekly Sheet','effective_date','2026-11-23','source_rows',(SELECT jsonb_agg(to_jsonb(s) ORDER BY source_row) FROM daycare_master_source s),'mappings',(SELECT jsonb_agg(to_jsonb(m) ORDER BY customer_number,source_pet) FROM daycare_master_mapping m),'notes',(SELECT jsonb_agg(to_jsonb(x)) FROM daycare_master_notes x),'corrections',jsonb_build_array('Zoey rows 56 and 57 are identical and map to one enrolment','Tatertot Thursday T validated against Detailed Sheet and retained as Thursday','Ruth SK04043 whitespace trimmed','Unknown weekdays retained provisionally for Ocean and Knox','Existing profile names and breeds preserved; Tugg breed discrepancy flagged'),'new_customers',2,'new_pets',9,'enrolments',149,'weekly_visits',240,'financial_before',original_finance,'financial_after',final_finance));
 RAISE NOTICE 'Daycare import passed: 149 dogs, 109 customers, 240 visits; no financial or customer-message changes';
END $import$;